```sop
@slots literal
{"seatA": 5, "seatB": 3, "seatC": 3, "threshold": 6}

@answer jsEval
const seats = {A: $slots.seatA, B: $slots.seatB, C: $slots.seatC};
const coalitions = [
  {members: "A+B", total: seats.A + seats.B},
  {members: "A+C", total: seats.A + seats.C},
  {members: "B+C", total: seats.B + seats.C}
];
const minimal = coalitions.filter((c) => {
  const isMembersArray = c.members.split("+");
  return c.total >= $slots.threshold && isMembersArray.every((m) => c.total - seats[m] < $slots.threshold);
});
return "The minimal winning coalitions are: " + minimal.map((c) => c.members).join(", ") + ".";
```

